```json
{
  "root_causes": [
    {
      "service": "ts-basic-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, c.span_name, round(c.duration/1e6,0) AS client_ms, round(s.duration/1e6,1) AS callee_server_ms, round(epoch_ms(s.time) - epoch_ms(c.time),0) AS start_gap_ms, round((epoch_ms(c.time)+c.duration/1e6) - (epoch_ms(s.time)+s.duration/1e6),0) AS end_gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-basic-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.duration>40e9 ORDER BY c.duration DESC",
          "claim": "Basic-to-station calls take 44-139 s client-side while station's server span takes 4-7 ms, with large gaps before and after."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_source, attr_destination, count(*) AS samples, round(sum(value),1) AS total_drops FROM abnormal_metrics_sum WHERE metric='hubble_drop_total' AND attr_source LIKE '%ts-station-service%' AND attr_destination LIKE '%ts-basic-service%' GROUP BY ALL",
          "claim": "Hubble records 52 dropped packets from ts-station-service to ts-basic-service in the abnormal period; none in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, span_name, count(*) AS n, round(quantile_cont(duration,0.95)/1e6,0) AS p95_ms, round(max(duration)/1e6,0) AS max_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY ALL",
          "claim": "Basic's outgoing POST calls show multi-second to 139 s latency in the abnormal period, while the same callees answer in milliseconds."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, count(*) AS n, round(max(duration)/1e6,0) AS max_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Server' AND duration>50e9 GROUP BY ALL",
          "claim": "Travel server spans stall for 50-130 s, and one returns HTTP 500 after its call to basic fails."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, round(duration/1e6,0) AS ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' AND duration>50e9",
          "claim": "Route-plan quickestRoute and minStopStations server spans take 62-129 s, with one 500 response."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, round(duration/1e6,0) AS ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' AND duration>50e9",
          "claim": "Travel-plan quickest server spans take about 120-130 s and return 500 when route-plan stalls."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, count(*) AS n, round(quantile_cont(duration,0.95)/1e6,0) AS p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND duration>15e9 GROUP BY ALL",
          "claim": "Ui-dashboard user-facing requests reach 20 s (client timeout) in the abnormal period, versus p95 164 ms in normal."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT a.service_name, a.span_name, round(a.duration/1e6,0) AS ms FROM abnormal_traces a WHERE a.service_name='ts-ui-dashboard' AND a.attr_span_kind='Server' AND a.span_name LIKE '%trips/left%' AND a.duration>15e9",
          "claim": "Ui-dashboard trips/left requests that go through travel service exceed 20 s in the abnormal period."
        }
      ]
    }
  ]
